  c as (select p.*, t.id as tid, t.club as tclub, md5(concat_ws('|', t.id::bigint::text, coalesce(t.player_name, '~'), coalesce(t.club, '~'), coalesce(t.first_year::int::text, '~'), coalesce(t.last_year::int::text, '~'), coalesce(t.nationality, '~'), coalesce(t.position, '~'))) as h_now, md5(concat_ws('|', t.id::bigint::text, coalesce(t.player_name, '~'), coalesce(p.old_club, '~'), coalesce(t.first_year::int::text, '~'), coalesce(t.last_year::int::text, '~'), coalesce(t.nationality, '~'), coalesce(t.position, '~'))) as h_old from p left join public.soccer_player_club_stints t on t.id = p.id)
  select count(*) filter (where tid is null), count(*) filter (where tid is not null and h_now = h),
         count(*) filter (where tid is not null and h_now <> h and tclub = new_club and h_old = h)
    into s_missing, s_match, s_already from c;
  s_drift := s_want - s_missing - s_match - s_already;
  with p as (select (x->>'id')::bigint as id, x->>'h' as h, x->>'old' as old_club, x->>'new' as new_club from jsonb_array_elements(payload::jsonb -> 'market') x)
  update public.player_market_values t set club = p.new_club from p where t.id = p.id and md5(concat_ws('|', t.id::bigint::text, coalesce(t.player_name, '~'), coalesce(t.club, '~'), coalesce(t.year::int::text, '~'), coalesce(t.age::int::text, '~'), coalesce(t.nationality, '~'), coalesce(t.position, '~'), coalesce(round(t.market_value_usd)::bigint::text, '~'))) = p.h;
  get diagnostics m_done = row_count;
  with p as (select (x->>'id')::bigint as id, x->>'h' as h, x->>'old' as old_club, x->>'new' as new_club from jsonb_array_elements(payload::jsonb -> 'stints') x)
  update public.soccer_player_club_stints t set club = p.new_club from p where t.id = p.id and md5(concat_ws('|', t.id::bigint::text, coalesce(t.player_name, '~'), coalesce(t.club, '~'), coalesce(t.first_year::int::text, '~'), coalesce(t.last_year::int::text, '~'), coalesce(t.nationality, '~'), coalesce(t.position, '~'))) = p.h;
  get diagnostics s_done = row_count;
  raise notice 'Round 1587: % market rows and % stint rows rewritten, % already current, % drifted, % missing',
    m_done, s_done, m_already + s_already, m_drift + s_drift, m_missing + s_missing;
end $r1587$;
